import React from 'react';

const SENTIMENT_COLOR = { positive: '#3ecf8e', negative: '#f06060', neutral: '#7a7a9a' };

function MeterBar({ value, total, color }) {
  const pct = total ? Math.round((value / total) * 100) : 0;
  return (
    <div style={{ display: 'flex', alignItems: 'center', gap: 8 }}>
      <div style={{
        flex: 1, height: 4, background: '#2a2a3a', borderRadius: 99, overflow: 'hidden'
      }}>
        <div style={{
          width: `${pct}%`, height: '100%', background: color,
          transition: 'width 0.8s ease', borderRadius: 99
        }} />
      </div>
      <span style={{ fontSize: 12, color: '#9090b0', minWidth: 32, textAlign: 'right' }}>
        {pct}%
      </span>
    </div>
  );
}

export default function StatsBar({ stats, loading }) {
  if (loading) {
    return (
      <div style={{ display: 'grid', gridTemplateColumns: 'repeat(auto-fit, minmax(200px, 1fr))', gap: 16, marginBottom: 32 }}>
        {[...Array(4)].map((_, i) => (
          <div key={i} className="skeleton" style={{ height: 96, borderRadius: 12 }} />
        ))}
      </div>
    );
  }

  if (!stats) return null;

  const { total, sentiment_breakdown: sb, avg_sentiment_score, top_categories } = stats;
  const topCat = top_categories?.[0]?.name || '–';
  const avgScore = avg_sentiment_score ?? 0;
  const moodLabel = avgScore > 0.2 ? 'Optimistic' : avgScore < -0.2 ? 'Pessimistic' : 'Mixed';
  const moodColor = avgScore > 0.2 ? '#3ecf8e' : avgScore < -0.2 ? '#f06060' : '#f5c842';

  const statCards = [
    {
      label: 'Total Articles',
      value: total,
      sub: `${top_categories?.length || 0} categories`,
      accent: '#f5c842',
    },
    {
      label: 'Top Category',
      value: topCat.charAt(0).toUpperCase() + topCat.slice(1),
      sub: `${top_categories?.[0]?.count || 0} articles`,
      accent: '#a78bfa',
    },
    {
      label: 'Overall Mood',
      value: moodLabel,
      sub: `Score: ${avgScore.toFixed(2)}`,
      accent: moodColor,
    },
  ];

  return (
    <div style={{ marginBottom: 32 }}>
      {/* Stat cards */}
      <div style={{
        display: 'grid',
        gridTemplateColumns: 'repeat(auto-fit, minmax(180px, 1fr))',
        gap: 16,
        marginBottom: 16
      }}>
        {statCards.map(({ label, value, sub, accent }) => (
          <div key={label} className="fade-in" style={{
            background: '#12121a',
            border: '1px solid #2a2a3a',
            borderRadius: 12,
            padding: '18px 20px',
          }}>
            <div style={{ fontSize: 11, textTransform: 'uppercase', letterSpacing: 2, color: '#5a5a7a', marginBottom: 6 }}>
              {label}
            </div>
            <div style={{ fontSize: 24, fontWeight: 700, color: accent, fontFamily: 'Playfair Display, serif' }}>
              {value}
            </div>
            <div style={{ fontSize: 12, color: '#5a5a7a', marginTop: 2 }}>{sub}</div>
          </div>
        ))}

        {/* Sentiment breakdown card */}
        <div className="fade-in" style={{
          background: '#12121a',
          border: '1px solid #2a2a3a',
          borderRadius: 12,
          padding: '18px 20px',
        }}>
          <div style={{ fontSize: 11, textTransform: 'uppercase', letterSpacing: 2, color: '#5a5a7a', marginBottom: 10 }}>
            Sentiment Split
          </div>
          {['positive', 'negative', 'neutral'].map(s => (
            <div key={s} style={{ marginBottom: 8 }}>
              <div style={{ display: 'flex', justifyContent: 'space-between', fontSize: 12, marginBottom: 3 }}>
                <span style={{ textTransform: 'capitalize', color: SENTIMENT_COLOR[s] }}>{s}</span>
                <span style={{ color: '#5a5a7a' }}>{sb?.[s] ?? 0}</span>
              </div>
              <MeterBar value={sb?.[s] ?? 0} total={total} color={SENTIMENT_COLOR[s]} />
            </div>
          ))}
        </div>
      </div>
    </div>
  );
}
